window.SB_EXTRA_ANSWERS = {"A Textbook of Mathematics Grade IX (KPTBB, English medium)":{"1.2|2|i":{"answer":"$A' = B$: A and B are the transpose of each other.","steps":[{"en":"Writing the rows of A as columns gives $\\begin{bmatrix} a_1 & b_1 \\\\ a_2 & b_2 \\end{bmatrix} = B$."}]},"1.2|2|ii":{"answer":"$B' = A$: A and B are the transpose of each other.","steps":[{"en":"Writing the rows of B as columns gives A."}]},"1.2|2|iii":{"answer":"$C' = D$: C and D are the transpose of each other.","steps":[{"en":"The rows $(-3, 1, -1)$ and $(4, 2, 7)$ of C are the columns of D."}]},"1.2|2|iv":{"answer":"$D' = C$: C and D are the transpose of each other.","steps":[{"en":"The columns of D are the rows of C."}]},"1.2|3|i":{"answer":"Not symmetric.","steps":[{"en":"$a_{12} = -7$ but $a_{21} = -1$, so $A' \\neq A$."}]},"1.2|3|ii":{"answer":"Symmetric.","steps":[{"en":"$a_{12} = a_{21} = 2$, so $B' = B$."}]},"1.2|3|iii":{"answer":"Not symmetric.","steps":[{"en":"$a_{12} = 4$ but $a_{21} = 5$."}]},"1.2|3|iv":{"answer":"Not symmetric.","steps":[{"en":"D is a $2 \\times 3$ matrix; only a square matrix can be symmetric."}]},"1.2|4|i":{"answer":"Skew-symmetric.","steps":[{"en":"The diagonal is 0 and $a_{12} = 4 = -a_{21}$, so $A' = -A$."}]},"1.2|4|ii":{"answer":"Skew-symmetric.","steps":[{"en":"The diagonal is 0 and $a_{12} = -5 = -a_{21}$, so $B' = -B$."}]},"1.2|4|iii":{"answer":"Not skew-symmetric (it is symmetric).","steps":[{"en":"$a_{12} = a_{21} = 7$, so $C' = C$; skew-symmetry needs $a_{21} = -a_{12}$."}]},"1.2|4|iv":{"answer":"Skew-symmetric.","steps":[{"en":"The diagonal is 0 and $a_{12} = 3 = -a_{21}$, $a_{13} = 2 = -a_{31}$, $a_{23} = 1 = -a_{32}$, so $D' = -D$."}]},"1.3|14|i":{"answer":"$A + B = [0 \\ \\ 0 \\ \\ 0] = O$, so $B = -A$.","steps":[{"en":"Each pair of corresponding entries adds up to 0."}]},"1.3|14|ii":{"answer":"$C + D = O$ (the $2 \\times 2$ null matrix), so $D = -C$.","steps":[{"en":"$a + (-a) = 0$, $-b + b = 0$, $-c + c = 0$, $d + (-d) = 0$."}]},"1.3|14|iii":{"answer":"$E + F = O$ (the $3 \\times 3$ null matrix), so $F = -E$.","steps":[{"en":"Every entry of F is the negative of the entry of E in the same place."}]},"1.3|1|i":{"answer":"Defined: $A + B$ is a $2 \\times 3$ matrix.","steps":[{"en":"A and B have the same order, $2 \\times 3$."}]},"1.3|1|ii":{"answer":"Not defined.","steps":[{"en":"B is $2 \\times 3$ and D is $2 \\times 2$: matrices of different orders cannot be added."}]},"1.3|1|iii":{"answer":"Not defined.","steps":[{"en":"$3A$ is $2 \\times 3$ and $2C$ is $2 \\times 2$: different orders."}]},"1.3|1|iv":{"answer":"Defined: $7C + 2D$ is a $2 \\times 2$ matrix.","steps":[{"en":"C and D are both $2 \\times 2$. (The printed key lists this one as (ii).)"}]},"1.4|1|i":{"answer":"A is $2 \\times 1$: $AB$ ($2 \\times 2$) and $AD$ ($2 \\times 3$) are defined, and $CA$ ($2 \\times 1$) is defined with A second. Conformable products: $AB, BA, CA, BC, AD$.","steps":[{"en":"A product $XY$ is defined when the number of columns of X equals the number of rows of Y."}]},"1.4|1|ii":{"answer":"B is $1 \\times 2$: $BA$ ($1 \\times 1$) and $BC$ ($1 \\times 2$) are defined, and $AB$ is defined with B second. Conformable products: $AB, BA, CA, BC, AD$.","steps":[{"en":"B has 2 columns, which match the 2 rows of A and of C."}]},"1.4|1|iii":{"answer":"C is $2 \\times 2$: $CA$ ($2 \\times 1$) is defined, and $BC$ ($1 \\times 2$) is defined with C second. Conformable products: $AB, BA, CA, BC, AD$.","steps":[{"en":"C has 2 rows and 2 columns, matching A (2 rows) and B (2 columns)."}]},"1.4|1|iv":{"answer":"D is $1 \\times 3$: only $AD$ ($2 \\times 3$) is defined, with D second. Conformable products: $AB, BA, CA, BC, AD$.","steps":[{"en":"D has 3 columns and none of A, B, C has 3 rows, so D cannot come first."}]},"1.5|2|i":{"answer":"Non-singular.","steps":[{"en":"$|A| = 5 \\cdot 1 - 3 \\cdot 2 = -1 \\neq 0$."}]},"1.5|2|ii":{"answer":"Singular.","steps":[{"en":"$|B| = 3 \\cdot 4 - (-6)(-2) = 12 - 12 = 0$."}]},"1.5|2|iii":{"answer":"Non-singular (for $a, b \\neq 0$).","steps":[{"en":"$|C| = 3a \\cdot b - (-2b)(2a) = 3ab + 4ab = 7ab \\neq 0$."}]},"1.5|2|iv":{"answer":"Singular.","steps":[{"en":"$|D| = (-3)(-4) - 6 \\cdot 2 = 12 - 12 = 0$."}]},"13.1|8|a":{"answer":"Yes.","steps":[{"en":"The sum of any two sides is greater than the third: $2 + 2 > 2$."}]},"13.1|8|b":{"answer":"Yes.","steps":[{"en":"$3 + 4 > 5$, $3 + 5 > 4$, $4 + 5 > 3$."}]},"13.1|8|c":{"answer":"No.","steps":[{"en":"$5 + 2 = 7$ is less than 8, so the two shorter sides cannot reach across the longest."}]},"13.1|8|d":{"answer":"Yes.","steps":[{"en":"$3 + 2 > 3$ and $3 + 3 > 2$."}]},"13.1|8|e":{"answer":"No.","steps":[{"en":"$1\\frac{1}{2} + 3\\frac{1}{2} = 5$, which is not greater than 5: the three lengths would lie on a straight line."}]},"13.1|8|f":{"answer":"Yes.","steps":[{"en":"$2\\frac{1}{2} + 3\\frac{1}{2} = 6 > 4\\frac{1}{2}$, and the other two sums are larger still."}]},"16.1|1|i":{"answer":"$\\triangle PBC$ and $\\triangle QBC$ are equal in area.","steps":[{"en":"They stand on the same base BC and lie between the same parallels PQ and BC."}]},"16.1|1|ii":{"answer":"$\\triangle BRP$ and $\\triangle CRQ$ are equal in area.","steps":[{"en":"$\\triangle BRP = \\triangle PBC - \\triangle RBC$ and $\\triangle CRQ = \\triangle QBC - \\triangle RBC$; the two triangles on the right are equal by (i)."}]},"16.1|1|iii":{"answer":"$\\triangle PQB$ and $\\triangle PQC$ are equal in area.","steps":[{"en":"They stand on the same base PQ and lie between the same parallels PQ and BC."}]},"16.1|1|iv":{"answer":"$\\triangle ABQ$ and $\\triangle ACP$ are equal in area.","steps":[{"en":"$\\triangle ABQ = \\triangle APQ + \\triangle PQB$ and $\\triangle ACP = \\triangle APQ + \\triangle PQC$; $\\triangle PQB = \\triangle PQC$ by (iii)."}]},"17.2|1|i":{"answer":"The three angle bisectors meet at one point, the incentre; the inradius is about 1.08 cm.","steps":[{"en":"Construct the triangle with AB = 4.5 cm, BC = 3.1 cm, CA = 5.2 cm (arcs from the ends of one side)."},{"en":"Bisect each of the three angles with compass arcs and a ruler."},{"en":"The three bisectors pass through one point I, the incentre. Check: the perpendicular distance from I to each side is the same, about 1.08 cm."}]},"17.2|1|ii":{"answer":"The three angle bisectors meet at one point, the incentre (also the centroid of an equilateral triangle); the inradius is about 3.46 for side 12.","steps":[{"en":"Construct the equilateral triangle of side 12 (all three arcs of radius 12)."},{"en":"Bisect the three angles (each 60° becomes 30°): the bisectors meet at the incentre, and the distance from it to each side is $12/(2\\sqrt{3}) \\approx 3.46$."}]},"17.2|1|iii":{"answer":"The three angle bisectors meet at one point, the incentre; the triangle has $\\angle B = 60^\\circ$, $BC \\approx 4.74$ cm, $AB \\approx 6.47$ cm, and the inradius is about 1.56 cm.","steps":[{"en":"Draw CA = 5.8 cm, make $\\angle A = 45^\\circ$ and $\\angle C = 75^\\circ$; the rays meet at B."},{"en":"Bisect the three angles: the bisectors meet at the incentre, equally far (about 1.56 cm) from the three sides."}]},"17.2|2|i":{"answer":"The three altitudes meet at one point, the orthocentre. The triangle (6, 4.5, 5.5 cm) is acute, so the orthocentre lies inside it.","steps":[{"en":"Construct the triangle with PQ = 6 cm, QR = 4.5 cm, PR = 5.5 cm."},{"en":"From each vertex draw the perpendicular to the opposite side; the three lines meet at the orthocentre H, inside the triangle because $6^2 < 4.5^2 + 5.5^2$ (all angles acute)."}]},"17.2|2|ii":{"answer":"The three altitudes meet at one point, the orthocentre. The triangle has $PR \\approx 6.31$ cm and is obtuse at Q ($\\approx 97.2^\\circ$), so the orthocentre lies outside it.","steps":[{"en":"Draw QR = 3.9 cm, make $\\angle R = 45^\\circ$ and cut off PQ = 4.5 cm with an arc from Q on the ray from R: $\\sin P = 3.9 \\sin 45^\\circ / 4.5$ gives $P \\approx 37.8^\\circ$, so $Q \\approx 97.2^\\circ$."},{"en":"Draw the altitudes (extend the sides where needed); they meet outside the triangle."}]},"17.2|2|iii":{"answer":"The three altitudes meet at one point, the orthocentre. The third angle is $R = 45^\\circ$, so the triangle is acute and the orthocentre lies inside.","steps":[{"en":"Draw PQ = 6 cm, make $\\angle P = 70^\\circ$ and $\\angle Q = 65^\\circ$; the rays meet at R ($\\angle R = 45^\\circ$)."},{"en":"Draw the altitudes from P, Q and R: they meet at the orthocentre H inside the triangle."}]},"17.2|3|i":{"answer":"The three perpendicular bisectors meet at one point, the circumcentre. The triangle (7, 6.5, 5.8 cm) is acute, so the circumcentre lies inside; the circumradius is about 3.75 cm.","steps":[{"en":"Construct the triangle with UV = 7 cm, VW = 6.5 cm, WU = 5.8 cm."},{"en":"Draw the perpendicular bisector of each side (arcs of equal radius from both ends); they meet at O, equally far from U, V and W."}]},"17.2|3|ii":{"answer":"The three perpendicular bisectors meet at one point, the circumcentre. The triangle is obtuse at W, so the circumcentre lies outside it; $UV \\approx 12.63$ cm and the circumradius is about 7.29 cm.","steps":[{"en":"Draw VW = 10 cm, make $\\angle W = 120^\\circ$ and cut off WU = 4.2 cm; then $UV = \\sqrt{10^2 + 4.2^2 - 2(10)(4.2)\\cos 120^\\circ} \\approx 12.63$ cm."},{"en":"Draw the three perpendicular bisectors; they meet at O outside the triangle, equally far (about 7.29 cm) from U, V and W."}]},"17.2|3|iii":{"answer":"The three perpendicular bisectors meet at one point, the circumcentre (the centre of an equilateral triangle); the circumradius is about 0.46 m.","steps":[{"en":"Construct the equilateral triangle of side 0.8 m."},{"en":"The perpendicular bisectors meet at the centre O; its distance to each vertex is $0.8/\\sqrt{3} \\approx 0.46$ m."}]},"17.2|4|i":{"answer":"The three medians meet at one point, the centroid, which divides each median 2 : 1 from the vertex. The triangle has $\\angle Z = 45^\\circ$, $XY \\approx 3.00$ cm, $XZ \\approx 3.68$ cm.","steps":[{"en":"Draw YZ = 4.1 cm, make $\\angle Y = 60^\\circ$ and $\\angle Z = 45^\\circ$ (since $\\angle X = 75^\\circ$); the rays meet at X."},{"en":"Bisect each side to find its midpoint and join it to the opposite vertex: the three medians meet at the centroid G, with $XG : G(\\text{midpoint}) = 2 : 1$."}]},"17.2|4|ii":{"answer":"The three medians meet at one point, the centroid, which divides each median 2 : 1 from the vertex. The triangle has $\\angle Z = 60^\\circ$, $YZ \\approx 5.87$ cm, $XY \\approx 5.27$ cm.","steps":[{"en":"Draw ZX = 4.3 cm, make $\\angle X = 75^\\circ$ and $\\angle Z = 60^\\circ$; the rays meet at Y ($\\angle Y = 45^\\circ$)."},{"en":"Draw the three medians: they meet at the centroid G, 2 : 1 from each vertex."}]},"17.2|4|iii":{"answer":"The three medians meet at one point, the centroid, which divides each median 2 : 1 from the vertex.","steps":[{"en":"Construct the triangle with XY = 4.5 cm, YZ = 3.4 cm, ZX = 5.6 cm ($4.5 + 3.4 > 5.6$, so it exists)."},{"en":"Join each vertex to the midpoint of the opposite side: the medians meet at the centroid G, and each is cut 2 : 1 at G."}]},"3.3|3|i":{"answer":"$3.3938$","steps":[{"en":"2476 = 2.476 × 10³: characteristic 3, mantissa .3938 from the tables."}]},"3.3|3|ii":{"answer":"$0.3802$","steps":[{"en":"2.4 lies between 1 and 10: characteristic 0, mantissa .3802."}]},"3.3|3|iii":{"answer":"$1.9661$","steps":[{"en":"92.5 = 9.25 × 10: characteristic 1, mantissa .9661."}]},"3.3|3|iv":{"answer":"$2.6836$","steps":[{"en":"482.7 = 4.827 × 10²: characteristic 2, mantissa .6836 from the tables (a calculator gives 2.6837). The printed key numbers this answer (vi)."}]},"3.3|3|v":{"answer":"$\\bar{1}.8938$","steps":[{"en":"0.783 = 7.83 × 10⁻¹: characteristic $\\bar{1}$, mantissa .8938. The printed key numbers this answer (vii)."}]},"3.3|3|vi":{"answer":"$\\bar{2}.9808$","steps":[{"en":"0.09566 = 9.566 × 10⁻²: characteristic $\\bar{2}$, mantissa .9808. The printed key numbers this answer (viii)."}]},"3.3|3|vii":{"answer":"$\\bar{3}.8283$","steps":[{"en":"0.006735 = 6.735 × 10⁻³: characteristic $\\bar{3}$, mantissa .8283. The printed key numbers this answer (ix)."}]},"3.3|3|viii":{"answer":"$2.8451$","steps":[{"en":"700 = 7 × 10²: characteristic 2, mantissa .8451. The printed key numbers this answer (x)."}]},"4.1|1|i":{"answer":"A polynomial.","steps":[{"en":"Every power of y is a whole number (0, 1, 2, 3) and the coefficients are real numbers."}]},"4.1|1|ii":{"answer":"Not a polynomial.","steps":[{"en":"$\\dfrac{5}{x^2}$ and $\\dfrac{3}{4x + 1}$ have the variable in a denominator (negative power of x)."}]},"4.1|1|iii":{"answer":"Not a polynomial.","steps":[{"en":"It contains $\\sqrt{x} = x^{1/2}$ (a power that is not a whole number) and a denominator with x."}]},"4.1|2|i":{"answer":"Not in its lowest terms: it equals $5(y + 1)$.","steps":[{"en":"$\\dfrac{5y^2 - 5}{y - 1} = \\dfrac{5(y - 1)(y + 1)}{y - 1}$ has the common factor $y - 1$. (The printed key says the opposite: it lists (i) and (iii) as lowest terms.)"}]},"4.1|2|ii":{"answer":"In its lowest terms.","steps":[{"en":"$\\dfrac{x^2 - 9}{x - 2} = \\dfrac{(x - 3)(x + 3)}{x - 2}$: the numerator and denominator have no common factor. (The printed key says it is not.)"}]},"4.1|2|iii":{"answer":"Not in its lowest terms: it equals $\\dfrac{1}{x - y}$.","steps":[{"en":"$\\dfrac{x + y}{x^2 - y^2} = \\dfrac{x + y}{(x - y)(x + y)}$ has the common factor $x + y$."}]},"4.7|1|i":{"answer":"A surd.","steps":[{"en":"The book's test: a number is a surd when it is irrational, a root, and a root of a rational number. $\\sqrt[3]{81} = 3\\sqrt[3]{3}$ is an irrational cube root of a rational number."}]},"4.7|1|ii":{"answer":"Not a surd.","steps":[{"en":"It is the square root of $1 + \\sqrt{5}$, which is irrational: it is not a root of a rational number. (The printed key lists (i), (ii).)"}]},"4.7|1|iii":{"answer":"A surd.","steps":[{"en":"$\\sqrt{\\sqrt{5}} = \\sqrt[4]{5}$, an irrational fourth root of the rational number 5."}]},"4.7|1|iv":{"answer":"A surd.","steps":[{"en":"$\\sqrt[4]{32} = 2\\sqrt[4]{2}$ is an irrational root of a rational number."}]},"4.7|1|v":{"answer":"Not a surd.","steps":[{"en":"$\\pi$ is irrational but it is not a root of a rational number."}]},"4.7|1|vi":{"answer":"Not a surd.","steps":[{"en":"It is the square root of $1 + \\pi^2$, which is irrational, not rational."}]},"8.2|4|a":{"answer":"A straight line through $(-3, 0)$ and $(0, 6)$.","steps":[{"en":"Write $y = 2x + 6$ and make a table: $x = -3 \\Rightarrow y = 0$; $x = -1 \\Rightarrow y = 4$; $x = 0 \\Rightarrow y = 6$."},{"en":"Plot $(-3, 0)$, $(-1, 4)$, $(0, 6)$ and join them with a ruler: the line has slope 2."}]},"8.2|4|b":{"answer":"A straight line through $(0, 1)$ and $(1, 0)$ (slope $-1$).","steps":[{"en":"Table for $y = 1 - x$: $x = -1 \\Rightarrow y = 2$; $x = 0 \\Rightarrow y = 1$; $x = 1 \\Rightarrow y = 0$; $x = 2 \\Rightarrow y = -1$."},{"en":"Plot the points and join them: the line falls from left to right."}]},"8.2|4|c":{"answer":"A horizontal line through $(0, 2)$, parallel to the x-axis.","steps":[{"en":"Every point of the line has $y = 2$ whatever x is: $(-2, 2)$, $(0, 2)$, $(3, 2)$."},{"en":"Plot these points and draw the line through them."}]},"8.2|4|d":{"answer":"A straight line through the origin with slope 1: $(-2, -2)$, $(0, 0)$, $(3, 3)$.","steps":[{"en":"Table for $y = x$: $x = -2 \\Rightarrow y = -2$; $x = 0 \\Rightarrow y = 0$; $x = 3 \\Rightarrow y = 3$."},{"en":"Plot the points and join them: the line bisects the angle between the positive axes."}]},"R11|1|ix":{"answer":"a) Perpendicular","steps":[{"en":"The diagonals of a square are perpendicular (they are also congruent, option c); they are never parallel."}]},"R12|1|vii":{"answer":"Options a, b and c are all true; d is false.","steps":[{"en":"Options a, b and c are all true for an equilateral triangle (its perpendicular bisectors are congruent, concurrent and also its angle bisectors); d is false, since perpendicular bisectors of a triangle meet at a point."}]},"R16|1|iv":{"answer":"b) Equal in area","steps":[{"en":"Parallelograms on the same base and between the same parallels are equal in area; they need not be congruent or similar."}]},"R1|1|ii":{"answer":"c) a diagonal matrix","steps":[{"en":"The only non-zero entries are on the diagonal and 4 ≠ −12, so it is a diagonal matrix; a scalar matrix would need equal diagonal entries."}]},"R1|1|iii":{"answer":"b) $\\begin{bmatrix} 1 & 2 \\\\ -3 & -1 \\end{bmatrix}$","steps":[{"en":"For A = [a b; c d] the adjoint is [d −b; −c a], so adj A = [1 2; −3 −1]."}]},"R1|1|iv":{"answer":"d) $\\begin{bmatrix} -4 & 3 \\\\ 3 & -2 \\end{bmatrix}$","steps":[{"en":"det A = 2·4 − 3·3 = −1, so A⁻¹ = (1/−1)·[4 −3; −3 2] = [−4 3; 3 −2]."}]},"R1|1|v":{"answer":"c) 0.6","steps":[{"en":"The matrix is not invertible when its determinant is 0: 5d − 2(1.5) = 5d − 3 = 0, so d = 0.6."}]},"R1|1|vii":{"answer":"b) $\\begin{bmatrix} 1 & -2 \\\\ 0 & 1 \\end{bmatrix}$","steps":[{"en":"The determinant of [1 2; 0 1] is 1, so its inverse is [1 −2; 0 1]."}]},"R1|1|viii":{"answer":"c) $-1$","steps":[{"en":"The determinant is 4·2 − (−1)(−9) = 8 − 9 = −1."}]},"R7|1|i":{"answer":"c) $x = 12$ and $x = 0$","steps":[{"en":"½|x − 6| − 4 = −1 gives |x − 6| = 6, so x = 12 or x = 0."}]},"R7|1|iii":{"answer":"b) $\\{\\ \\}$","steps":[{"en":"√x = −10 has no solution: a square root is never negative (squaring gives x = 100, which does not satisfy it). The solution set is empty."}]},"R7|1|vi":{"answer":"a) $\\left\\{\\dfrac{1}{5}\\right\\}$","steps":[{"en":"√(5x + 3) = 2 gives 5x + 3 = 4, so x = 1/5, and it checks."}]},"R7|1|vii":{"answer":"a) $\\{3\\}$","steps":[{"en":"|5x/3| = 5 gives x = 3 or x = −3. Option a is the closest: it prints only {3}, but the solution set is {3, −3}."}]},"R7|1|viii":{"answer":"d) $\\{0\\}$","steps":[{"en":"|−x| = 0 only when x = 0, so the solution set is {0}."}]},"R8|1|i":{"answer":"d) Quadrant IV","steps":[{"en":"(5, −2): x positive and y negative is the fourth quadrant."}]},"R8|1|iii":{"answer":"b) Quadrant II","steps":[{"en":"(−3, 8): x negative and y positive is the second quadrant."}]},"R8|1|v":{"answer":"c) Quadrant III","steps":[{"en":"(−6, −6): both negative is the third quadrant."}]},"R8|1|vi":{"answer":"a) $y$-axis","steps":[{"en":"x = a is a vertical line, which is parallel to the y-axis."}]},"R9|1|vii-ix":{"answer":"Figure questions: (vii) b, (viii) d, (ix) a, as printed in the key.","steps":[{"en":"The figure (points A, B, C, D on a graph) is not in the book data, so these three could not be re-checked."}]},"R9|1|x":{"answer":"b) $\\sqrt{18}$","steps":[{"en":"|AB| = √((0 − 3)² + (3 − 0)²) = √18 (which is 3√2, not 9√2)."}]}},"Mathematics 10 (KPTBB)":{"Review 10|1|i":{"answer":"a) an arc","steps":[{"en":"A part of a circle such as ACB is an arc."}]},"Review 10|1|ii":{"answer":"a) $\\overline{OT} \\perp \\overleftrightarrow{PQ}$","steps":[{"en":"The radial segment to the point of contact is perpendicular to the tangent."}]},"Review 10|1|iii":{"answer":"b) equal","steps":[{"en":"Two tangents drawn from a point outside a circle are equal in length."}]},"Review 11|1|i":{"answer":"a) $3\\sqrt{2}$","steps":[{"en":"The chord of a 90° arc is r√2 = 3√2."}]},"Review 11|1|ii":{"answer":"a) $\\overline{AB} \\cong \\overline{CD}$","steps":[{"en":"Equal arcs of a circle have equal chords: AB ≅ CD."}]},"Review 12|1|ii":{"answer":"d) $30°$","steps":[{"en":"An inscribed angle is half the central angle on the same arc: 60° ÷ 2 = 30°."}]},"Review 13|1|i":{"answer":"a) $\\dfrac{\\pi}{3}$","steps":[{"en":"The exterior angle of a regular hexagon is 360° ÷ 6 = 60° = π/3."}]},"Review 13|1|ii":{"answer":"a) parallel","steps":[{"en":"Tangents at the ends of a diameter are both perpendicular to it, so they are parallel."}]},"Review 13|1|iii":{"answer":"b) 2","steps":[{"en":"Exactly two tangents can be drawn from a point outside a circle."}]},"Review 13|1|iv":{"answer":"c) touch each other externally","steps":[{"en":"When the distance between the centres equals the sum of the radii, the circles touch externally."}]},"Review 1|1|i":{"answer":"d) $x = -1, 5$","steps":[{"en":"Each factor equals zero: x + 1 = 0 gives x = −1 and x − 5 = 0 gives x = 5."}]},"Review 1|1|ii":{"answer":"c) $\\dfrac{1 \\pm \\sqrt{5}}{2}$","steps":[{"en":"By the quadratic formula x = (1 ± √(1 + 4)) / 2 = (1 ± √5) / 2."}]},"Review 1|1|iii":{"answer":"d) cannot be simplified","steps":[{"en":"√5 is irrational and −1 ± √5 has no common factor with 2, so the expression cannot be simplified further."}]},"Review 1|1|iv":{"answer":"c) $a = 2, b = -1, c = -3$","steps":[{"en":"Write 2x² − x = 3 as 2x² − x − 3 = 0: a = 2, b = −1, c = −3."}]},"Review 1|1|ix":{"answer":"d) $x = 3$ or $x = 5$","steps":[{"en":"x² − 8x + 15 = (x − 3)(x − 5) = 0, so x = 3 or x = 5."}]},"Review 1|1|v":{"answer":"a) $x = 4, -1$","steps":[{"en":"x² − 3x − 4 = (x − 4)(x + 1) = 0, so x = 4 or x = −1."}]},"Review 1|1|vi":{"answer":"b) $x = \\dfrac{-2 \\pm \\sqrt{22}}{2}$","steps":[{"en":"x = (−4 ± √(16 + 72)) / 4 = (−4 ± √88) / 4 = (−2 ± √22) / 2."}]},"Review 1|1|vii":{"answer":"a) $x = \\pm\\dfrac{1}{2}$","steps":[{"en":"x² = 1/4, so x = ±1/2."}]},"Review 1|1|viii":{"answer":"a) 2 or −9","steps":[{"en":"x² + 7x − 18 = (x + 9)(x − 2) = 0, so x = 2 or x = −9."}]},"Review 2|1|i":{"answer":"c) 2","steps":[{"en":"Sum of the roots = −(2a + 3)/(a + 1) = −7/3, so 6a + 9 = 7a + 7 and a = 2."}]},"Review 2|1|ii":{"answer":"a) $x^2 - 2x - 15 = 0$","steps":[{"en":"With sum s = 2 and product p: s³ − 3ps = 98 gives 8 − 6p = 98, so p = −15 and the equation is x² − 2x − 15 = 0."}]},"Review 2|1|iii":{"answer":"d) none of these","steps":[{"en":"If b² < 4ac the roots are not real, and when they are real both are negative; so none of a, b, c is true for every such equation."}]},"Review 2|1|iv":{"answer":"b) $\\dfrac{3}{7}$","steps":[{"en":"1/a + 1/b = (a + b)/(ab) = (3/4) ÷ (7/4) = 3/7."}]},"Review 3|1|i":{"answer":"c) $a \\propto b$","steps":[{"en":"Direct variation is written a ∝ b."}]},"Review 3|1|ii":{"answer":"d) $mn = k$","steps":[{"en":"m ∝ 1/n means m = k/n, so mn = k."}]},"Review 3|1|iii":{"answer":"d) 3 to 2","steps":[{"en":"30/45, 4 to 6 and 2 : 3 all equal 2/3; 3 to 2 is 3/2."}]},"Review 3|1|iv":{"answer":"c) $\\dfrac{a}{c} = \\dfrac{b}{d}$","steps":[{"en":"Alternendo: if a/b = c/d then a/c = b/d."}]},"Review 3|1|ix":{"answer":"b) $\\dfrac{\\ell a + mc + ne}{\\ell b + md + nf}$","steps":[{"en":"If a/b = c/d = e/f = k, then (ℓa + mc + ne)/(ℓb + md + nf) = k as well."}]},"Review 3|1|v":{"answer":"a) $x = 21$","steps":[{"en":"7/9 = x/27, so x = 7 × 3 = 21."}]},"Review 3|1|vi":{"answer":"c) $\\dfrac{y^2}{x}$","steps":[{"en":"The third proportional z of x and y satisfies x : y = y : z, so z = y²/x."}]},"Review 3|1|vii":{"answer":"b) $x \\propto z$","steps":[{"en":"y ∝ 1/z gives 1/y ∝ z, and x ∝ 1/y, so x ∝ z."}]},"Review 3|1|viii":{"answer":"b) $a = \\dfrac{11}{2}$","steps":[{"en":"(2a + 1)/21 = 4/7, so 2a + 1 = 12 and a = 11/2."}]},"Review 3|1|x":{"answer":"d) $x = \\dfrac{7}{16}y$","steps":[{"en":"x = (7/16)y has the form x = ky, so x varies directly as y."}]},"Review 4|1|i":{"answer":"c) $\\dfrac{1}{2(x - 1)} - \\dfrac{1}{2(x + 1)}$","steps":[{"en":"1/(x² − 1) = 1/((x − 1)(x + 1)) = 1/(2(x − 1)) − 1/(2(x + 1))."}]},"Review 4|1|ii":{"answer":"a) Rational fraction","steps":[{"en":"P(x)/Q(x) with Q(x) ≠ 0 is a rational fraction."}]},"Review 4|1|iii":{"answer":"b) Improper fraction","steps":[{"en":"Numerator and denominator both have degree 2, so it is an improper fraction."}]},"Review 4|1|iv":{"answer":"c) $x^2 - 3x + 1$","steps":[{"en":"Synthetic division by x − 5 gives 1, −3, 1 with remainder 0, so the quotient is x² − 3x + 1."}]},"Review 5|1|i":{"answer":"d) An onto function from A to B","steps":[{"en":"Every element of A has one image and the range {4, 5} is all of B: an onto function (not one-one, since 1 and 3 both go to 4)."}]},"Review 5|1|ii":{"answer":"c) $2^6$","steps":[{"en":"A × B has 2 × 3 = 6 elements and every subset of it is a relation: 2⁶."}]},"Review 5|1|iii":{"answer":"d) $\\{0, 4, 8, 12\\}$ and $\\{6, 10, 14, 18\\}$","steps":[{"en":"{0, 4, 8, 12} and {6, 10, 14, 18} have no common element."}]},"Review 5|1|iv":{"answer":"b) 13","steps":[{"en":"U has 15 elements and R ∩ S = {1, 7} has 2, so (R ∩ S)′ has 13."}]},"Review 5|1|v":{"answer":"a) Range $f$ = B","steps":[{"en":"A function is onto when its range equals B."}]},"Review 5|1|vi":{"answer":"a) $\\{0, 8, 10, 14\\}$","steps":[{"en":"The domain is the set of first elements: {0, 8, 10, 14}."}]},"Review 6|1|i":{"answer":"b) Class interval","steps":[{"en":"The difference between the upper limits of consecutive classes is the class interval."}]},"Review 6|1|ii":{"answer":"c) Ogive","steps":[{"en":"A cumulative frequency graph is called an ogive."}]},"Review 6|1|iii":{"answer":"a) frequency","steps":[{"en":"The number of times a value occurs is its frequency."}]},"Review 6|1|iv":{"answer":"a) 1","steps":[{"en":"The value 1 occurs five times, more than any other, so the mode is 1."}]},"Review 6|1|ix":{"answer":"d) 7","steps":[{"en":"The value 7 occurs three times, more than any other."}]},"Review 6|1|v":{"answer":"a) 1, 2, 3, 3, 2, 1, 2","steps":[{"en":"1, 1, 2, 2, 2, 3, 3: mean 14/7 = 2, median 2, mode 2 and range 3 − 1 = 2."}]},"Review 6|1|vi":{"answer":"c) geometric mean","steps":[{"en":"The n-th root of the product of n values is the geometric mean."}]},"Review 6|1|vii":{"answer":"b) 66","steps":[{"en":"The middle value of 63, 65, 66, 67, 69 is 66."}]},"Review 6|1|viii":{"answer":"a) 51","steps":[{"en":"Arranged: 41, 43, 47, 51, 52, 57, 59; the middle (4th) value is 51."}]},"Review 6|1|x":{"answer":"b) 0","steps":[{"en":"All values are equal, so there is no spread: the standard deviation is 0."}]},"Review 6|1|xi":{"answer":"d) Rs. 600/-","steps":[{"en":"30 × Rs. 20 = Rs. 600."}]},"Review 6|1|xii":{"answer":"d) none of these","steps":[{"en":"1500 ÷ 30 = 50, which is not among a, b, c."}]},"Review 6|1|xiii":{"answer":"c) Range","steps":[{"en":"The largest value minus the smallest value is the range."}]},"Review 6|1|xiv":{"answer":"a) Arithmetic Mean","steps":[{"en":"Σx / n is the arithmetic mean."}]},"Review 6|1|xv":{"answer":"c) 0.5","steps":[{"en":"Median of Set A = (2 + 3)/2 = 2.5; mean of Set B = 18/6 = 3; the difference is 0.5."}]},"Review 6|1|xvi":{"answer":"d) Variance","steps":[{"en":"Σf(x − x̄)² / Σf is the variance."}]},"Review 6|1|xvii":{"answer":"c) Mode","steps":[{"en":"The most frequent value is the mode."}]},"Review 7|1|i":{"answer":"b) angle of elevation","steps":[{"en":"An object above the observer is seen at an angle of elevation."}]},"Review 7|1|ii":{"answer":"c) $\\dfrac{\\cos\\theta}{\\sin\\theta}$","steps":[{"en":"cot θ = cos θ / sin θ."}]},"Review 7|1|iii":{"answer":"d) $\\sec^2\\theta$","steps":[{"en":"1 + tan²θ = sec²θ."}]},"Review 7|1|iv":{"answer":"c) $-\\dfrac{1}{\\sqrt{2}}$","steps":[{"en":"tan θ = 1 gives θ = 45° or 225°; in the third quadrant sin θ is negative: −1/√2."}]},"Review 7|1|v":{"answer":"a) 1st quadrant","steps":[{"en":"−350° + 360° = 10°, which lies in the first quadrant."}]},"Review 7|1|vi":{"answer":"b) $\\dfrac{\\pi}{4}$","steps":[{"en":"45° = 45 × π/180 = π/4."}]},"Review 7|1|vii":{"answer":"d) 2.6496","steps":[{"en":"Adjacent side = hypotenuse × cos 58° = 5 × 0.5299 = 2.6496."}]},"Review 7|1|viii":{"answer":"c) 0.4","steps":[{"en":"tan P = MN / NP = 8/21 ≈ 0.38, which is 0.4 to the nearest tenth."}]},"Review 8|1|i":{"answer":"b) Greek","steps":[{"en":"Pythagoras was a Greek mathematician."}]},"Review 8|1|ii":{"answer":"a) Perga","steps":[{"en":"Apollonius was born in Perga."}]},"Review 8|1|iii":{"answer":"d) Mathematician","steps":[{"en":"Apollonius of Perga was a mathematician."}]},"Review 9|1|i":{"answer":"a) congruent","steps":[{"en":"Chords that are equally distant from the centre of a circle are congruent."}]},"Review 9|1|ii":{"answer":"c) CD is closer to O","steps":[{"en":"The longer chord is nearer the centre, so CD (the longer) is closer to O."}]},"Review 9|1|iii":{"answer":"c) 24 centimeters","steps":[{"en":"Half the chord = √(13² − 5²) = 12, so the chord is 24 cm."}]},"Review 9|1|iv":{"answer":"a) 15 units","steps":[{"en":"Distance = √(25² − 20²) = 15 units."}]},"Review 9|1|v":{"answer":"b) 8 units","steps":[{"en":"r = √((4√3)² + 4²) = √64 = 8 units."}]},"Review 9|1|vi":{"answer":"b) 6 cm","steps":[{"en":"Half the chord = √(5² − 4²) = 3, so the chord is 6 cm."}]},"Review 9|1|vii":{"answer":"b) 8","steps":[{"en":"OE = 5 − 2 = 3 and half of BD = √(5² − 3²) = 4, so BD = 8."}]}}};
